"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[807],{2045:e=>{e.exports=JSON.parse('{"title":"บริษัท โรสเซลล์ จำกัด ประเทศไทย","body":"โรสเซลล์ เป็นผู้นำเข้าและจำหน่าย Propylene Glycol Alginate (PGA) ไม่เจือปน ในประเทศไทยจากผู้ผลิตชั้นนำด้าน Alginate ของโลก KIMICA Corporation ประเทศญี่ปุ่น\\n\\nบริษัท โรสเซลล์ จำกัด ก่อตั้งเมื่อปี พ.ศ. 2547 เป็นผู้นำเข้าวัตถุเจือปนอาหารเพื่อตอบสนองความต้องการที่เพิ่มขึ้นอย่างก้าวกระโดดของผู้ผลิตอาหารในประเทศไทย โรสเซลล์ไม่หยุดพัฒนาตัวเลือกสินค้าของเราและปรับเปลี่ยนไปตามความต้องการของตลาดเพื่อความพึงพอใจสูงสุดของลูกค้า\\nมากกว่า 15 ปีที่ดำเนินกิจการมา เราได้นำเข้าสินค้าหลายประเภท อาทิ กลิ่น, Tapioca Starch, Vital Wheat Gluten, และ Propylene Glycol Alginate (PGA) สินค้าทุกประเภทที่เรานำเข้ามาผ่านมาตรฐานฟู้ดเกรด (Food Grade) และได้รับมาตรฐานอื่นๆเช่น Halal หรือ ISO ขึ้นอยู่กับแต่ละประเภทสินค้า \\nปัจจุบัน โรสเซลล์ จำหน่าย Propylene Glycol Alginate (PGA) ซึ่งผลิตโดยผู้เชี่ยวชาญด้าน Alginate ระดับโลก KIMICA Corporation ประเทศญี่ปุ่น \\nโรสเซลล์ให้ความสำคัญอย่างสูงสุดเสมอมาเกี่ยวกับคุณภาพของสินค้าที่เรานำเข้าและผู้ผลิตเพื่อให้มั่นใจว่าลูกค้าของเราจะได้รับความพึงพอใจสูงสุด","table":{"title":"ข้อมูลบริษัท","companyName":{"title":"ชื่อ","value":"บริษัท โรสเซลล์ จำกัด"},"establishedDate":{"title":"ก่อตั้ง","value":"พฤษภาคม พ.ศ. 2546"},"registrationNo":{"title":"เลขทะเบียนบริษัท","value":"0105546053371"},"capital":{"title":"ทุนจดทะเบียน","value":"1,000,000 บาท"},"address":{"title":"สำนักงานใหญ่","value":"111/63 หมู่ 7 แขวง บางไผ่ เขต บางแค กรุงเทพฯ 10160"}}}')}}]);